style.css:
@-moz-document domain("tiktok.com") {
/* Fundo geral fixado no html e no body */
  html, body {
    background-image: linear-gradient(rgba(30, 15, 25, 0.7), rgba(30, 15, 25, 0.7)),
      url("data:image/webp;base64,") !important;
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
  }

  /* Remove fundos sólidos que normalmente cobrem o body */
  #app,
  #main,
  #main-content-homepage_hot,
  #main-content-others_homepage,
  [class*="DivBodyContainer"],
  [class*="DivContainer"],
  [class*="DivRootContainer"] {
    background-color: transparent !important;
    background-image: none !important;
  }

  /* Cards de vídeo com fundo semi-transparente pra combinar */
  div[data-e2e="recommend-list-item-container"],
  div[data-e2e="user-post-item"],
  div[data-e2e="user-post-item-list"],
  [class*="DivItemContainer"] {
    background-color: rgba(40, 20, 35, 0.4) !important;
    backdrop-filter: blur(3px);
    border-radius: 12px;
  }

  /* Barra lateral e topo */
  [class*="DivSideNavContainer"],
  [class*="DivTopNavContainer"],
  header, aside, nav {
    background-color: rgba(30, 15, 25, 0.65) !important;
  }

  /* Textos com tom mais claro pra manter legibilidade */
  h1, h2, h3, span, p {
    color: #fbeaf2 !important;
  }

  /* Scrollbar combinando com o tema */
  ::-webkit-scrollbar-thumb {
    background-color: #d98fae !important;
    border-radius: 10px;
  }
  ::-webkit-scrollbar-track {
    background-color: rgba(30, 15, 25, 0.6) !important;
  }
}
